={{ JSON.stringify({
  query: `query MarketingContext($productsFirst: Int!, $ordersFirst: Int!, $orderQuery: String!) {
    shop { name currencyCode }
    products(first: $productsFirst, sortKey: UPDATED_AT, reverse: true, query: "status:active") {
      nodes {
        id title handle status descriptionHtml productType vendor tags updatedAt
        variants(first: 10) { nodes { id sku price } }
      }
    }
    orders(first: $ordersFirst, sortKey: CREATED_AT, reverse: true, query: $orderQuery) {
      nodes {
        id name createdAt processedAt
        currentTotalPriceSet { shopMoney { amount currencyCode } }
        lineItems(first: 100) {
          nodes {
            quantity
            discountedTotalSet { shopMoney { amount currencyCode } }
            product { id title handle }
            variant { id sku price }
          }
        }
      }
    }
  }`,
  variables: {
    productsFirst: $('⚙️ Configuration').first().json.maxProducts,
    ordersFirst: $('⚙️ Configuration').first().json.maxOrders,
    orderQuery: 'financial_status:paid created_at:>=' + $('⚙️ Configuration').first().json.sinceDate
  }
}) }}

