const p=$input.first().json;
if(p.errors?.length) throw new Error('Shopify GraphQL: '+JSON.stringify(p.errors));
const d=p.data||{};
const products=d.products?.nodes||[];
const orders=d.orders?.nodes||[];
const stats=new Map();
for(const product of products){
  stats.set(product.id,{productId:product.id,title:product.title,handle:product.handle,status:product.status,productType:product.productType||'',vendor:product.vendor||'',tags:product.tags||[],updatedAt:product.updatedAt||'',price:Number(product.variants?.nodes?.[0]?.price||0),sku:product.variants?.nodes?.[0]?.sku||'',description:String(product.descriptionHtml||'').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim().slice(0,2500),revenue:0,units:0,orders:new Set()});
}
let totalRevenue=0;
const currency=d.shop?.currencyCode||'EUR';
for(const order of orders){
  totalRevenue+=Number(order.currentTotalPriceSet?.shopMoney?.amount||0);
  for(const li of (order.lineItems?.nodes||[])){
    const id=li.product?.id; if(!id||!stats.has(id)) continue;
    const s=stats.get(id);
    s.units+=Number(li.quantity||0);
    s.revenue+=Number(li.discountedTotalSet?.shopMoney?.amount||0);
    s.orders.add(order.id);
  }
}
const list=[...stats.values()].map(s=>({...s,orderCount:s.orders.size,orders:undefined})).sort((a,b)=>b.revenue-a.revenue);
const opportunities=[...list].sort((a,b)=>a.revenue-b.revenue).slice(0,10);
return [{json:{
  shop:{name:d.shop?.name||'Shopify',currency},
  period:{days:$('⚙️ Configuration').first().json.days,since:$('⚙️ Configuration').first().json.sinceDate,generatedAt:new Date().toISOString()},
  totals:{revenue:Number(totalRevenue.toFixed(2)),orders:orders.length,activeProducts:products.length},
  products:list,
  topProducts:list.slice(0,10),
  opportunities
}}];

