function parseAI(p){
 const t=String(p?.choices?.[0]?.message?.content||'').trim().replace(/^```(?:json)?\s*/i,'').replace(/```\s*$/,'').trim();
 const a=t.indexOf('{'),b=t.lastIndexOf('}'); const s=(a>=0&&b>=a)?t.slice(a,b+1):t;
 try{return JSON.parse(s)}catch(e){return {parseError:true,raw:s.slice(0,12000),error:e.message}}
}
